{"source":"#include<stdio.h>
#include<string.h>
    int main(int argc, char *argv[]){
		 int i,j,n,arr[100],ANS,max = 0;

		 scanf("%d",&n);

		 for(i = 0; i < n; i++)
			 scanf("%d",&arr[i]);

		 for(i = 0; i < n; i++)
		 { 
			 ANS = 0;
			 for(j = i ; j < n; j++)
			 {
				 ANS = ANS ^ arr[j];     
				 if(ANS > max)
					 max = ANS;
			 }
		 }
		 printf("%d\n",max);

		 return 0;
	 }
"}
